'use strict';
const Housing=(()=>{
 const catalog=[
  {id:'small',name:'บ้านหลังเล็ก',price:180000,upkeep:7200,comfort:1,access:0,description:'ห้องนอนหนึ่งห้อง ครัวเล็ก และพื้นที่เก็บของจำเป็น'},
  {id:'comfortable',name:'บ้านกว้างพร้อมห้องทำงาน',price:380000,upkeep:15600,comfort:2,access:2,description:'แยกมุมพักจากงาน มีพื้นที่ให้ครอบครัวและการฝึกวิชา'},
  {id:'villa',name:'วิลล่าพร้อมสวน',price:950000,upkeep:38000,comfort:3,access:5,description:'ห้องรับแขก สวน และพื้นที่ดูแลสหาย ต้องจ่ายค่าบำรุงมากขึ้น'},
  {id:'manor',name:'คฤหาสน์ประจำตระกูล',price:2800000,upkeep:112000,comfort:4,access:9,description:'หอหนังสือ เรือนรับรอง และผู้ดูแลที่ได้รับค่าจ้าง'},
  {id:'estate',name:'ตำหนักพร้อมเขตที่ดิน',price:8500000,upkeep:340000,comfort:5,access:14,description:'อาคารหลายหลังและเขตคุ้มครอง ต้องรับภาระภาษีและคนดูแลทั้งปี'}
 ];
 const nativeNames={cave:['โพรงพักที่คุ้มลม','ถ้ำพร้อมลานฝึก','โถงถ้ำหลายชั้น','รังใหญ่มีเขตเฝ้า','รังบรรพกาลทั้งแนวผา'],reef:['จุดยึดในแนวปะการัง','แนวปะการังที่ฟื้นไว้','แอ่งพักใต้แนวหิน','โถงน้ำพร้อมเขตเลี้ยง','เขตอนุบาลแนวปะการัง'],ocean:['ช่องหินในทะเลลึก','เขตพักใต้กระแสสงบ','แอ่งน้ำลึกคุ้มครอง','อาณาเขตแนวสันทะเล','เขตพักมหาสมุทร'],river:['แอ่งพักริมน้ำ','แนวพักหลายกระแส','แอ่งน้ำมีทางหลบ','โถงพักใต้ลำน้ำ','เขตคุ้มครองต้นธาร'],root:['จุดยึดรากที่ชุ่ม','แนวรากพร้อมแหล่งน้ำ','เครือรากและลานแสง','พงรากคุ้มครอง','เขตรากโบราณ'],spirit:['จุดยึดที่สงบ','แนวสัญญาณมั่นคง','วงแสงพร้อมจุดพัก','โถงความทรงจำ','เขตยึดโยงบรรพกาล'],marsh:['แอ่งพักหลบลม','หนองน้ำพร้อมแนวหลบ','แอ่งพักหลายช่วงน้ำ','เขตน้ำคุ้มครอง','ระบบหนองน้ำที่ฟื้นไว้']};
 const round=n=>Math.round(n*100)/100;
 function ensure(s){const h=LifeSpending.ensure(s).home;if(h.tier===undefined){h.tier=h.owned?0:-1;h.paid=h.owned?300000:0;h.native=false}return h}
 function native(s){return RaceDrives.cashless(s)}
 function option(s,i){const d=catalog[i],p=Ecology.profile(s),names=nativeNames[p.habitat]||['เขตพักที่มั่นคง','แนวพักพร้อมแหล่งเสบียง','ถิ่นพักหลายส่วน','เขตคุ้มครองร่วมถิ่น','อาณาเขตพักบรรพกาล'];return {...d,tier:i,name:s.race!==0&&p.strict?names[i]:d.name,cost:native(s)?[35,50,70,85,95][i]:d.price,unit:native(s)?'แหล่งถิ่น':'ทอง',annual:native(s)?[2,4,6,8,10][i]:d.upkeep}}
 function value(s){const h=ensure(s);return !h.owned||h.native?0:round(h.paid*.82+h.improvements*3750)}
 function upkeep(s){const h=ensure(s);return h.owned&&!h.native?catalog[Math.max(0,h.tier)].upkeep:0}
 function reason(s,i){const h=ensure(s),o=option(s,i);return !LifeSpending.allowed(s)?'ตอบเรื่องที่ค้างอยู่ก่อน':Engine.biological(s)<18?'ยังไม่ถึงวัยจัดการถิ่นของตน':h.tier>=i?'มีที่พักระดับนี้หรือสูงกว่าแล้ว':native(s)?s.raceDrives.resource<o.cost?'แหล่งถิ่นยังไม่พอ':SpeciesSociety.metrics(s).access<25+i*12?'สิทธิร่วมถิ่นยังไม่พอขยายเขต':'':s.gold+value(s)<o.cost?'เงินพร้อมใช้รวมมูลค่าขายที่พักเดิมยังไม่พอ':''}
 function buy(s,i){if(!Number.isInteger(i)||i<0||i>=5||reason(s,i))return false;const h=ensure(s),o=option(s,i),old=value(s),cost=o.cost;if(native(s))s.raceDrives.resource-=cost;else{s.gold=round(s.gold+old-cost);Economy.record(s,'otherSpend',cost);if(old)Economy.record(s,'otherIncome',old)}h.owned=true;h.tier=i;h.paid=native(s)?0:cost;h.native=native(s);h.improvements=0;const fixtures=[['bed'],['desk','bookcase'],['reading-lamp','garden-bed'],['hearth','telescope'],['crystal-tree','egg-warmer']];for(const id of fixtures.slice(0,i+1).flat()){const item=LifeChoices.shop.find(x=>x.id===id);if(item&&Ecology.itemAllowed(s,item)&&!s.lifeChoices.inventory.includes(id))s.lifeChoices.inventory.push(id)}Narrative.append(s,{title:'ที่พักใหม่ · '+o.name,paragraphs:[native(s)?'คุณค่อย ๆ ฟื้นแนวพักให้เหมาะกับร่าง สิทธิร่วมถิ่นและแหล่งดำรงชีวิตต้องคอยดูแลต่อเนื่อง':'คุณตรวจเอกสาร รับกุญแจ และกันงบค่าบำรุง '+o.annual.toLocaleString('en-US')+' ทองต่อปีไว้ด้วย ความสบายใหม่นี้มีภาระที่ต้องรักษา'],kind:'spending',key:'housing-'+s.calendar.count+'-'+i,tone:'important',scene:Ecology.profile(s).scene,ecology:s.race!==0});return true}
 function sell(s){const h=ensure(s);if(!LifeSpending.allowed(s)||Engine.biological(s)<18||!h.owned||h.native)return false;const v=value(s);s.gold=round(Math.min(1e9,s.gold+v));Economy.record(s,'otherIncome',v);h.owned=false;h.tier=-1;h.paid=0;h.improvements=0;Narrative.append(s,{title:'คืนกุญแจของที่พักเดิม',paragraphs:['ขายที่พักหลังหักค่าธรรมเนียม ได้รับ '+v.toLocaleString('en-US')+' ทอง และกลับไปแบ่งค่าที่พักหรือเช่าตามแผนชีวิต'],kind:'spending',key:'housing-sell-'+s.calendar.count,scene:Ecology.profile(s).scene,ecology:s.race!==0});return true}
 function quarter(s){const h=ensure(s);if(!h.owned||!s.accepted||s.dead||h.lastQuarter===s.calendar.count)return;h.lastQuarter=s.calendar.count;if(h.native)s.raceDrives.resource=Math.max(0,s.raceDrives.resource-option(s,h.tier).annual/4);if(Engine.biological(s)>=18){s.joy=Math.min(100,s.joy+.12*(h.tier+1));if(s.race===0)s.lifeChoices.classStanding=Math.min(100,s.lifeChoices.classStanding+.015*catalog[h.tier].access)}}
 function valid(s){const h=s.spending?.home;if(!h||h.tier===undefined)return true;return Number.isInteger(h.tier)&&h.tier>=-1&&h.tier<5&&h.owned===(h.tier>=0)&&Number.isFinite(h.paid)&&h.paid>=0&&h.paid<=1e9&&typeof h.native==='boolean'&&(h.lastQuarter===undefined||Number.isInteger(h.lastQuarter)&&h.lastQuarter>=-1&&h.lastQuarter<=s.calendar.count)}
 return {catalog,ensure,option,value,upkeep,reason,buy,sell,quarter,valid};
})();
